		if sv, ok := entry.Surfaces[string(surface)]; ok && len(sv.candidates) > 0 {
			for _, candidate := range sv.candidates {
				if candidate != "" && out[candidate] == "" {
					out[candidate] = targetID
				}
			}
		}
	}
	return out
}

// SamplingProfile returns the catalog-defined sampling-parameter bundle for
// the given profile name (e.g., "code"). The second return value is false
// when the profile is not declared in the manifest. See ADR-007.
func (c *Catalog) SamplingProfile(name string) (sampling.Profile, bool) {
	p, ok := c.manifest.SamplingProfiles[name]
	return p, ok
}

// SamplingProfileNames returns the names of all sampling profiles declared
// in the manifest, sorted lexicographically. Used by `catalog show` and
// other ops surfaces to advertise what profiles are available.
func (c *Catalog) SamplingProfileNames() []string {
	if len(c.manifest.SamplingProfiles) == 0 {
		return nil
	}
	out := make([]string, 0, len(c.manifest.SamplingProfiles))
	for name := range c.manifest.SamplingProfiles {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// ModelSamplingControl returns the SamplingControl string for the model ID,
// or "" when the model is not declared in the catalog or carries no
// explicit value (treated as the default "client_settable" by callers).
// Implements the sampling.CatalogLookup interface.
func (c *Catalog) ModelSamplingControl(modelID string) string {
	entry, ok := c.LookupModel(modelID)
	if !ok {
		return ""
	}
	return entry.SamplingControl
}

// LookupModel returns the ModelEntry for the given model ID from the top-level
// models: map (manifest v4+). The second return value is false if not found.
func (c *Catalog) LookupModel(id string) (ModelEntry, bool) {
	if entry, ok := c.manifest.Models[id]; ok {
		return entry, true
	}
	for _, entry := range c.manifest.Models {
		for _, concrete := range entry.Surfaces {
			if concrete == id {
				return entry, true
			}
		}
	}
	if entry, ok := c.lookupModelVariant(id); ok {
		return entry, true
	}
	return ModelEntry{}, false
}

// ModelEligibility returns power and automatic-routing eligibility for a
// catalog model ID or any declared provider surface ID. Unknown models return
// ok=false; known models with missing/zero power remain exact-pin-capable but
// are not auto-routable.
func (c *Catalog) ModelEligibility(id string) (ModelEligibility, bool) {
	entry, ok := c.LookupModel(id)
	if !ok {
		for modelID, candidate := range c.manifest.Models {
			if strings.EqualFold(modelID, id) {
				entry = candidate
				ok = true
				break
			}
			for _, surfaceID := range candidate.Surfaces {
				if strings.EqualFold(surfaceID, id) {
					entry = candidate
					ok = true
					break
				}
			}
			if ok {
				break
			}
		}
		if !ok {
			return ModelEligibility{}, false
		}
	}
	return ModelEligibility{
		Power:        entry.Power,
		ExactPinOnly: entry.ExactPinOnly,
		AutoRoutable: entry.AutoRoutable(),
	}, true
}

// AllModelsInTier returns the ordered model entries declared as candidates for
// a target tier. For older manifests, candidates are synthesized from surface
// mappings during load.
func (c *Catalog) AllModelsInTier(targetID string) []TierModel {
	target, ok := c.manifest.Targets[targetID]
	if !ok {
		return nil
	}
	ids := targetCandidateIDs(target)
	out := make([]TierModel, 0, len(ids))
	for _, id := range ids {
		entry, ok := c.manifest.Models[id]
		if !ok {
			continue
		}
		out = append(out, TierModel{ID: id, Entry: entry})
	}
	return out
}

// ContextWindowForModel returns the context window in tokens for the given
// concrete model ID, or 0 if the model is not in the catalog or has no
// context_window declared. Used as a fallback when the provider's live API
// does not expose its context window (e.g. LM Studio's /v1/models omits it).
// Matching is case-insensitive to accept both "qwen3.5-27b" and "Qwen3.5-27B".
func (c *Catalog) ContextWindowForModel(id string) int {
	if entry, ok := c.LookupModel(id); ok {
		return entry.ContextWindow
	}
	return 0
}

// SupportsToolsForModel reports whether the given concrete model ID supports
// tool/function calling per the catalog. Returns true when the model is not
// in the catalog (caller assumes capable by default) and false only when the
// catalog explicitly marks the model with no_tools=true. Matching is
// case-insensitive to mirror ContextWindowForModel.
func (c *Catalog) SupportsToolsForModel(id string) bool {
	if c == nil {
		return true
	}
	if entry, ok := c.LookupModel(id); ok {
		return !entry.NoTools
	}
	return true
}

func (c *Catalog) lookupModelVariant(id string) (ModelEntry, bool) {
	id = strings.TrimSpace(id)
	if id == "" {
		return ModelEntry{}, false
	}
	for modelID, entry := range c.manifest.Models {
		if sameModelVariant(id, modelID) {
			return entry, true
		}
		for _, surfaceID := range entry.Surfaces {
			if sameModelVariant(id, surfaceID) {
				return entry, true
			}
		}
	}
	return ModelEntry{}, false
}

func sameModelVariant(a, b string) bool {
	ca := catalogModelKey(a)
	cb := catalogModelKey(b)
	if ca == "" || cb == "" {
		return false
	}
	if ca == cb {
		return true
	}
	if sameNamedFamilyMajor(a, b) {
		return true
	}
	if len(ca) < 8 || len(cb) < 8 {
		return false
	}
	return strings.Contains(ca, cb) || strings.Contains(cb, ca)
}

func catalogModelKey(s string) string {
	s = strings.TrimSpace(s)
	if slash := strings.Index(s, "/"); slash > 0 {
		s = s[slash+1:]
	}
	s = strings.ToLower(s)
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		}
	}
	return b.String()
}

func sameNamedFamilyMajor(a, b string) bool {
	familyA, majorA := namedFamilyMajor(a)
	familyB, majorB := namedFamilyMajor(b)
	return familyA != "" && familyA == familyB && majorA > 0 && majorA == majorB
}

func namedFamilyMajor(s string) (string, int) {
	tokens := catalogModelTokens(s)
	if len(tokens) == 0 {
		return "", 0
	}
	family := ""
	for _, token := range tokens {
		switch token {
		case "opus", "sonnet", "haiku":
			family = token
		}
	}
	if family == "" {
		return "", 0
	}
	for _, token := range tokens {
		n, err := strconv.Atoi(token)
		if err == nil {
			return family, n
		}
	}
	return family, 0
}

package modelcatalog

import (
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
)

func TestRoutingLegacyNamesDocPointsToPowerRouting(t *testing.T) {
	doc := readRoutingProfilesDoc(t)
	required := []string{
		"numeric power",
		"--min-power",
		"--max-power",
		"--model",
		"--provider",
		"--harness",
		"fiz --list-models",
		"compatibility data",
		"must not be used for new automation",
	}
	for _, text := range required {
		if !strings.Contains(doc, text) {
			t.Errorf("docs/routing/profiles.md missing %q", text)
		}
	}
	if strings.Contains(doc, "### `") {
		t.Fatal("docs/routing/profiles.md must not enumerate legacy routing names")
	}
}

func readRoutingProfilesDoc(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed")
	}
	repoRoot := filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
	data, err := os.ReadFile(filepath.Join(repoRoot, "docs", "routing", "profiles.md"))
	if err != nil {
		t.Fatalf("read docs/routing/profiles.md: %v", err)
	}
	return string(data)
}

package modelcatalog

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/sampling"
	"gopkg.in/yaml.v3"
)

const (
	statusActive     = "active"
	statusDeprecated = "deprecated"
	statusStale      = "stale"
	maxSchemaVersion = 4

	providerPreferenceLocalFirst        = "local-first"
	providerPreferenceSubscriptionFirst = "subscription-first"
	providerPreferenceLocalOnly         = "local-only"
	providerPreferenceSubscriptionOnly  = "subscription-only"
)

//go:embed catalog/models.yaml
var embeddedManifest []byte

// LoadOptions configures how a catalog manifest is loaded.
type LoadOptions struct {
	ManifestPath    string
	RequireExternal bool
}

// ModelEntry holds per-model metadata introduced in manifest v4.
type ModelEntry struct {
	Family             string                      `yaml:"family,omitempty"`
	DisplayName        string                      `yaml:"display_name,omitempty"`
	Tier               string                      `yaml:"tier,omitempty"`
	Status             string                      `yaml:"status,omitempty"`
	ProviderSystem     string                      `yaml:"provider_system,omitempty"`
	DeploymentClass    string                      `yaml:"deployment_class,omitempty" json:"deployment_class,omitempty"`
	PowerProvenance    PowerProvenance             `yaml:"power_provenance,omitempty" json:"power_provenance,omitempty"`
	CostInputPerM      float64                     `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64                     `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64                     `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64                     `yaml:"cost_cache_write_per_m,omitempty"`
	CostInputPerMTok   float64                     `yaml:"cost_input_per_mtok,omitempty"`
	CostOutputPerMTok  float64                     `yaml:"cost_output_per_mtok,omitempty"`
	SWEBenchVerified   float64                     `yaml:"swe_bench_verified,omitempty"`
	LiveCodeBench      float64                     `yaml:"live_code_bench,omitempty"`
	BenchmarkAsOf      string                      `yaml:"benchmark_as_of,omitempty"`
	OpenRouterID       string                      `yaml:"openrouter_id,omitempty"`
	OpenRouterRefID    string                      `yaml:"openrouter_ref_id,omitempty"`
	Surfaces           map[string]string           `yaml:"surfaces,omitempty"`
	SpeedTokensPerSec  float64                     `yaml:"speed_tokens_per_sec,omitempty"`
	ContextWindow      int                         `yaml:"context_window,omitempty"`
	Power              int                         `yaml:"power,omitempty" json:"power,omitempty"`
	ExactPinOnly       bool                        `yaml:"exact_pin_only,omitempty" json:"exact_pin_only,omitempty"`
	NoTools            bool                        `yaml:"no_tools,omitempty"`
	ReasoningMaxTokens int                         `yaml:"reasoning_max_tokens,omitempty"`
	ReasoningBudgets   map[reasoning.Reasoning]int `yaml:"reasoning_budgets,omitempty"`
	ReasoningLevels    []string                    `yaml:"reasoning_levels,omitempty"`
	ReasoningControl   string                      `yaml:"reasoning_control,omitempty"`
	ReasoningWire      string                      `yaml:"reasoning_wire,omitempty"`
	// SamplingControl declares whether catalog sampling_profiles reach the
	// wire for runs that resolve to this model. See ADR-007 §4.
	//   client_settable (default) — provider honors all five sampler fields.
	//   harness_pinned             — wrapped harness pins samplers internally;
	//                                 the resolver short-circuits to a
	//                                 zero-value bundle.
	//   partial                    — provider honors a subset (reserved; not
	//                                 enforced in v1).
	SamplingControl string `yaml:"sampling_control,omitempty"`
}

// PowerProvenance records why a model received its catalog power score.
type PowerProvenance struct {
	Method          string             `yaml:"method,omitempty" json:"method,omitempty"`
	Benchmarks      map[string]float64 `yaml:"benchmarks,omitempty" json:"benchmarks,omitempty"`
	Recency         string             `yaml:"recency,omitempty" json:"recency,omitempty"`
	CostInputPerM   float64            `yaml:"cost_input_per_m,omitempty" json:"cost_input_per_m,omitempty"`
	CostOutputPerM  float64            `yaml:"cost_output_per_m,omitempty" json:"cost_output_per_m,omitempty"`
	DeploymentClass string             `yaml:"deployment_class,omitempty" json:"deployment_class,omitempty"`
	OverrideReason  string             `yaml:"override_reason,omitempty" json:"override_reason,omitempty"`
}

// Reasoning capability control values.
const (
	ReasoningControlTunable = "tunable"
	ReasoningControlFixed   = "fixed"
	ReasoningControlNone    = "none"

	ReasoningWireProvider = "provider"
	ReasoningWireModelID  = "model_id"
	ReasoningWireNone     = "none"
)

// Sampling-control values for ModelEntry.SamplingControl. See ADR-007 §4.
const (
	SamplingControlClientSettable = "client_settable"
	SamplingControlHarnessPinned  = "harness_pinned"
	SamplingControlPartial        = "partial"
)

type manifest struct {
	Version        int                     `yaml:"version"`
	GeneratedAt    string                  `yaml:"generated_at"`
	CatalogVersion string                  `yaml:"catalog_version,omitempty"`
	Models         map[string]ModelEntry   `yaml:"models,omitempty"`
	Profiles       map[string]profileEntry `yaml:"profiles"`
	Targets        map[string]targetEntry  `yaml:"targets"`
	// SamplingProfiles is a map from profile name (e.g., "code") to a named
	// bundle of sampling-parameter overrides. Profile bundles are the L1
	// layer of the resolution chain; see ADR-007.
	SamplingProfiles map[string]sampling.Profile `yaml:"sampling_profiles,omitempty"`
}

type profileEntry struct {
	Target             string `yaml:"target"`
	ProviderPreference string `yaml:"provider_preference,omitempty"`
}

// surfaceValue represents a surface entry that may be a plain model ID string
// or a struct with a candidates list (v4+).
type surfaceValue struct {
	// model is set when the YAML value is a plain string.
	model string
	// candidates is set when the YAML value is a struct with a candidates list.
	candidates []string
}

// UnmarshalYAML decodes either a scalar string or a mapping with candidates.
func (s *surfaceValue) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		s.model = value.Value
		return nil
	case yaml.MappingNode:
		var raw struct {
			Candidates []string `yaml:"candidates"`
		}
		if err := value.Decode(&raw); err != nil {
			return err
		}
		s.candidates = raw.Candidates
		return nil
	default:
		return fmt.Errorf("surfaceValue: unexpected YAML node kind %v", value.Kind)
	}
}

// primaryModel returns the first/primary concrete model ID for this surface.
func (s surfaceValue) primaryModel() string {
	if s.model != "" {
		return s.model
	}
	if len(s.candidates) > 0 {
		return s.candidates[0]
	}
	return ""
}

// allCandidates returns an ordered list of candidate model IDs.
func (s surfaceValue) allCandidates() []string {
	if s.model != "" {
		return []string{s.model}
	}
	out := make([]string, len(s.candidates))
	copy(out, s.candidates)
	return out
}

type targetEntry struct {
	Family           string                        `yaml:"family"`
	Aliases          []string                      `yaml:"aliases"`
	Status           string                        `yaml:"status"`
	Replacement      string                        `yaml:"replacement,omitempty"`
	DeprecatedAt     string                        `yaml:"deprecated_at,omitempty"`
	Candidates       []string                      `yaml:"candidates,omitempty"`
	Surfaces         map[string]surfaceValue       `yaml:"surfaces"`
	SurfacePolicy    map[string]surfacePolicyEntry `yaml:"surface_policy,omitempty"`
	ContextWindowMin int                           `yaml:"context_window_min,omitempty"`
	SWEBenchMin      float64                       `yaml:"swe_bench_min,omitempty"`
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64 `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64 `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64 `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64 `yaml:"cost_cache_write_per_m,omitempty"`
	// Context and hardware
	ContextWindow int `yaml:"context_window,omitempty"` // max tokens
	// Benchmarks
	SWEBenchVerified float64 `yaml:"swe_bench_verified,omitempty"` // percent
	LiveCodeBench    float64 `yaml:"live_code_bench,omitempty"`    // percent
	BenchmarkAsOf    string  `yaml:"benchmark_as_of,omitempty"`    // YYYY-MM-DD
	// OpenRouter
	OpenRouterRefID string `yaml:"openrouter_ref_id,omitempty"` // OR model ID when different from surface model
}

type surfacePolicyEntry struct {
	ReasoningDefault       reasoning.Reasoning `yaml:"reasoning_default,omitempty"`
	PlacementOrder         []string            `yaml:"placement_order,omitempty"`
	MaxInputCostPerMTokUSD *float64            `yaml:"max_input_cost_per_mtok_usd,omitempty"`
	FailurePolicy          string              `yaml:"failure_policy,omitempty"`
}

func (s surfacePolicyEntry) toResolved() SurfacePolicy {
	return SurfacePolicy{
		ReasoningDefault:       s.ReasoningDefault,
		PlacementOrder:         append([]string(nil), s.PlacementOrder...),
		MaxInputCostPerMTokUSD: s.MaxInputCostPerMTokUSD,
		FailurePolicy:          s.FailurePolicy,
	}
}

// Default loads the embedded default catalog snapshot.
func Default() (*Catalog, error) {
	return Load(LoadOptions{})
}

// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
func Load(opts LoadOptions) (*Catalog, error) {
	data := embeddedManifest
	source := "embedded"

	if opts.ManifestPath != "" {
		externalData, err := os.ReadFile(opts.ManifestPath)
		if err != nil {
			if opts.RequireExternal {
				return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
			}
		} else {
			data = externalData
			source = opts.ManifestPath
		}
	}

	return loadManifest(data, source)
}

func loadManifest(data []byte, source string) (*Catalog, error) {
	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
	}
	upgradeManifest(&m)
	if err := validateManifest(m); err != nil {
		return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
	}

	catalog := &Catalog{
		manifest:       m,
		manifestSrc:    source,
		aliasToID:      make(map[string]string),
		profileEntries: make(map[string]profileEntry),
	}

	for profile, entry := range m.Profiles {
		catalog.profileEntries[profile] = entry

}

func catalogModelTokens(s string) []string {
	s = strings.TrimSpace(s)
	if slash := strings.Index(s, "/"); slash > 0 {
		s = s[slash+1:]
	}
	s = strings.ToLower(s)
	var out []string
	var b strings.Builder
	flush := func() {
		if b.Len() == 0 {
			return
		}
		out = append(out, b.String())
		b.Reset()
	}
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		default:
			flush()
		}
	}
	flush()
	return out
}

// CandidatesFor returns the ordered list of candidate concrete model IDs for
// the given surface and target key. For old-style single-string surfaces this
// returns a one-element slice. Returns nil if the target or surface is absent.
func (c *Catalog) CandidatesFor(surface Surface, targetKey string) []string {
	target, ok := c.manifest.Targets[targetKey]
	if !ok {
		return nil
	}
	if len(target.Candidates) > 0 {
		candidates := c.concreteModelsForSurface(target, surface)
		if len(candidates) == 0 {
			return nil
		}
		return candidates
	}
	sv, ok := target.Surfaces[string(surface)]
	if !ok {
		return nil
	}
	return sv.allCandidates()
}

// CatalogModelPricing holds per-million-token costs for a model as sourced from the catalog.
type CatalogModelPricing struct {
	InputPerMTok   float64
	OutputPerMTok  float64
	CacheReadPerM  float64
	CacheWritePerM float64
}

// AllModels returns all per-model entries from the top-level models: map
// (manifest v4+), keyed by model ID. Returns an empty map for older manifests.
func (c *Catalog) AllModels() map[string]ModelEntry {
	if len(c.manifest.Models) == 0 {
		return make(map[string]ModelEntry)
	}
	out := make(map[string]ModelEntry, len(c.manifest.Models))
	for id, e := range c.manifest.Models {
		out[id] = e
	}
	return out
}

// PricingFor returns pricing for all active concrete models across all surfaces.
// Per-model entries from the top-level models: map (v4+) take precedence over
// target-level pricing. Only models/targets with a positive input cost are
// included.
func (c *Catalog) PricingFor() map[string]CatalogModelPricing {
	result := make(map[string]CatalogModelPricing)

	for modelID, entry := range c.manifest.Models {
		input := entry.inputCostPerM()
		if input <= 0 {
			continue
		}
		result[modelID] = CatalogModelPricing{
			InputPerMTok:   input,
			OutputPerMTok:  entry.outputCostPerM(),
			CacheReadPerM:  entry.CostCacheReadPerM,
			CacheWritePerM: entry.CostCacheWritePerM,
		}
	}

	return result
}

func (c *Catalog) resolveTarget(ref, profile, targetID string, opts ResolveOptions) (ResolvedTarget, error) {
	if opts.Surface == "" {
		return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: targetID, Surface: opts.Surface}
	}

	target, ok := c.manifest.Targets[targetID]
	if !ok {
		return ResolvedTarget{}, &UnknownTargetError{CanonicalID: targetID}
	}
	status := normalizedStatus(target.Status)
	deprecated := status != statusActive
	if deprecated && !opts.AllowDeprecated {
		return ResolvedTarget{}, &DeprecatedTargetError{
			CanonicalID: targetID,
			Status:      status,
			Replacement: target.Replacement,
		}
	}

	concreteModel, modelEntry, hasModelEntry := c.primaryConcreteModel(target, opts.Surface)
	if concreteModel == "" {
		return ResolvedTarget{}, &MissingSurfaceError{
			CanonicalID: targetID,
			Surface:     opts.Surface,
		}
	}
	policy := SurfacePolicy{}
	if target.SurfacePolicy != nil {
		if entry, ok := target.SurfacePolicy[string(opts.Surface)]; ok {
			policy = entry.toResolved()
		}
	}

	resolved := ResolvedTarget{
		Ref:                ref,
		Profile:            profile,
		Family:             target.Family,
		CanonicalID:        targetID,
		ConcreteModel:      concreteModel,
		SurfacePolicy:      policy,
		Deprecated:         deprecated,
		Replacement:        target.Replacement,
		CatalogVersion:     c.manifest.CatalogVersion,
		ManifestSource:     c.manifestSrc,
		ManifestVersion:    c.manifest.Version,
		CostInputPerM:      target.CostInputPerM,
		CostOutputPerM:     target.CostOutputPerM,
		CostCacheReadPerM:  target.CostCacheReadPerM,
		CostCacheWritePerM: target.CostCacheWritePerM,
		ContextWindow:      target.ContextWindow,
		SWEBenchVerified:   target.SWEBenchVerified,
		LiveCodeBench:      target.LiveCodeBench,
		BenchmarkAsOf:      target.BenchmarkAsOf,
		OpenRouterRefID:    target.OpenRouterRefID,
	}
	if hasModelEntry {
		if modelEntry.Family != "" {
			resolved.Family = modelEntry.Family
		}
		resolved.CostInputPerM = modelEntry.inputCostPerM()
		resolved.CostOutputPerM = modelEntry.outputCostPerM()
		resolved.CostCacheReadPerM = modelEntry.CostCacheReadPerM
		resolved.CostCacheWritePerM = modelEntry.CostCacheWritePerM
		resolved.ContextWindow = modelEntry.ContextWindow
		resolved.SWEBenchVerified = modelEntry.SWEBenchVerified
		resolved.LiveCodeBench = modelEntry.LiveCodeBench
		resolved.BenchmarkAsOf = modelEntry.BenchmarkAsOf
		resolved.OpenRouterRefID = modelEntry.openRouterID()
	}
	return resolved, nil
}

func (c *Catalog) primaryConcreteModel(target targetEntry, surface Surface) (string, ModelEntry, bool) {
	if sv, ok := target.Surfaces[string(surface)]; ok {
		modelID := sv.primaryModel()
		entry, hasEntry := c.manifest.Models[modelID]
		return modelID, entry, hasEntry
	}
	for _, modelID := range target.Candidates {
		entry, ok := c.manifest.Models[modelID]
		if !ok {
			continue
		}
		if concrete := entry.Surfaces[string(surface)]; concrete != "" {
			return concrete, entry, true
		}
	}
	return "", ModelEntry{}, false
}

func (c *Catalog) concreteModelsForSurface(target targetEntry, surface Surface) []string {
	if len(target.Candidates) == 0 {
		if sv, ok := target.Surfaces[string(surface)]; ok {
			return sv.allCandidates()
		}
		return nil
	}
	out := make([]string, 0, len(target.Candidates))
	for _, modelID := range target.Candidates {
		entry, ok := c.manifest.Models[modelID]
		if !ok {
			continue
		}
		if concrete := entry.Surfaces[string(surface)]; concrete != "" {
			out = append(out, concrete)
		}
	}
	return out
}

func targetCandidateIDs(target targetEntry) []string {
	if len(target.Candidates) > 0 {
		out := make([]string, len(target.Candidates))
		copy(out, target.Candidates)
		return out
	}
	seen := make(map[string]bool)
	var out []string
	keys := make([]string, 0, len(target.Surfaces))
	for surface := range target.Surfaces {
		keys = append(keys, surface)
	}
	sort.Strings(keys)
	for _, surface := range keys {
		for _, modelID := range target.Surfaces[surface].allCandidates() {
			if modelID != "" && !seen[modelID] {
				seen[modelID] = true
				out = append(out, modelID)
			}
		}
	}
	return out
}

