			Family:          "frontier",
			Status:          statusActive,
			DeploymentClass: deploymentClassManagedCloudFrontier,
			CostInputPerM:   3,
			CostOutputPerM:  15,
			PowerProvenance: PowerProvenance{Method: "cost_recency", Recency: "2025-10-01"},
		},
	})

	assert.True(t, models["current"].AutoRoutable())
